using Addons.Addons;
using Core.All.Enums;
using Core.All.Serializable.Addon;
using Core.Client.Helpers;
using Games.Games;
using Ports.Ports.EDuke32;
using Tests.Unit.Helpers;

namespace Tests.Unit.CmdArguments;

/// <summary>
///     Tests for command-line arguments generated by the <see cref="VoidSW" /> port.
/// </summary>
public sealed class VoidSWCmdArgumentsTests
{
    /// <summary>
    ///     Shadow Warrior base campaign.
    /// </summary>
    private readonly GenericCampaign _wangCamp;

    /// <summary>
    ///     Shadow Warrior game instance.
    /// </summary>
    private readonly WangGame _wangGame;

    /// <summary>
    ///     Shadow Warrior loose map.
    /// </summary>
    private readonly LooseMap _wangLooseMap;

    /// <summary>
    ///     Shadow Warrior mods test setups.
    /// </summary>
    private readonly AutoloadModsTestSetups _wangMods;

    /// <summary>
    ///     Twin Dragon campaign.
    /// </summary>
    private readonly GenericCampaign _wangTdCamp;

    /// <summary>
    ///     Initializes a new instance of the <see cref="VoidSWCmdArgumentsTests" /> class.
    /// </summary>
    public VoidSWCmdArgumentsTests()
    {
        (_wangGame, _wangCamp, _wangTdCamp, _wangLooseMap, _wangMods) = PortTestSetups.Wang();
    }

    /// <summary>
    ///     Tests that VoidSW generates correct start arguments for Shadow Warrior.
    /// </summary>
    [Fact]
    public void WangTest()
    {
        var mods = _wangMods.StandardMods;

        VoidSW voidSw = new();

        var args = voidSw.GetStartGameArgs(_wangGame, _wangCamp, mods, [], true, true, 3);

        var expected = $"" +
                       $" -g\"{CmdArgsTestData.EnabledMod}\"" +
                       $" -mh\"{CmdArgsTestData.EnabledDef1}\"" +
                       $" -mh\"{CmdArgsTestData.EnabledDef2}\"" +
                       $" -g\"{CmdArgsTestData.ModIncompatibleWithAddon}\"" +
                       $" -g\"{CmdArgsTestData.IncompatibleModWithCompatibleVersion}\"" +
                       $" -g\"{CmdArgsTestData.DependentMod}\"" +
                       $" -g\"{CmdArgsTestData.DependentModWithCompatibleVersion}\"" +
                       $" -g\"{CmdArgsTestData.FeatureMod}\"" +
                       $" -j\"{Directory.GetCurrentDirectory()}\\Data\\Addons\\Wang\\Mods\"" +
                       " -j\"D:\\Games\\Wang\"" +
                       " -addon0" +
                       " -s3" +
                       " -quick" +
                       " -nosetup" +
                       " -usecwd" +
                       " -h\"a\"" +
                       "";

        CmdArgsAssert.Equal(expected, args);
    }

