        var args = voidSw.GetStartGameArgs(_wangGame, wangTc, [], [], true, true, 3);

        var expected = $"" +
                       $" -j\"D:\\Games\\Wang\"" +
                       " -addon0" +
                       $" -j\"{folderPath}\"" +
                       $" -g\"wang_tc.zip\"" +
                       " -s3" +
                       " -quick" +
                       " -nosetup" +
                       " -usecwd" +
                       " -h\"a\"" +
                       "";

        CmdArgsAssert.Equal(expected, args);
